import glob
R=[
('au Canada, par exemple, les pertes en capital ne peuvent','en France, par exemple, les moins-values de cession de valeurs mobilières s\'imputent en principe sur les plus-values de même nature réalisées la même année ou au cours des dix années suivantes, mais pas sur les autres revenus, et les opérations réalisées dans un PEA suivent leurs propres règles'),
('au Canada, par exemple, la règle sur les pertes apparentes','en France, par exemple, il n\'existe pas de règle générale équivalente à la « wash-sale rule » américaine, mais une cession suivie d\'un rachat immédiat des mêmes titres dans le seul but de constater une moins-value peut, dans certains cas, être contestée par l\'administration fiscale au titre de l\'abus de droit, par conséquent vérifiez ce point avec un conseiller fiscal'),
('au Canada, par exemple, le REER fonctionne','en France, par exemple, le plan d\'épargne retraite (PER) fonctionne un peu comme un compte traditionnel (versements déductibles dans certaines limites, sortie imposée), tandis que l\'assurance-vie et le PEA offrent une fiscalité allégée après une certaine durée de détention, sans être l\'équivalent exact d\'un compte Roth'),
('vérifiez vos droits de cotisation auprès de l\'Agence du revenu du Canada','vérifiez votre plafond de déduction épargne retraite, qui figure sur votre avis d\'impôt'),
('au Canada, par exemple, il n\'existe pas de majoration du coût','en France, par exemple, il n\'existe pas de majoration du coût à l\'américaine, mais les héritiers reçoivent les titres pour leur valeur au jour du décès, si bien que la plus-value latente n\'est pas imposée à l\'impôt sur le revenu; la succession peut en revanche être soumise aux droits de succession selon le lien de parenté, l\'assurance-vie suit un régime particulier et le Code civil réserve une part de la succession aux héritiers réservataires, par conséquent confirmez votre situation avec un notaire et un conseiller fiscal'),
('au Canada, par exemple, la convention avec les États-Unis','en France, par exemple, la convention fiscale franco-américaine limite en principe à 15 % la retenue à la source sur les dividendes américains, cette retenue ouvrant droit à un crédit d\'impôt imputable sur l\'impôt français, et le formulaire W-8BEN permet d\'appliquer ce taux réduit'),
('au Canada, par exemple, les dividendes déterminés','en France, par exemple, les dividendes sont en principe soumis au prélèvement forfaitaire unique (la « flat tax »), sauf option globale pour le barème progressif de l\'impôt sur le revenu, auquel cas un abattement de 40 % s\'applique, et ils ne sont pas imposés tant qu\'ils restent dans un PEA'),
('au Canada, par exemple, l\'avantage lié aux options','en France, par exemple, le gain tiré des options sur actions (stock-options) et des actions gratuites relève de régimes particuliers qui dépendent notamment de la date d\'attribution, une partie étant souvent imposée comme un salaire, par conséquent confirmez avec un conseiller fiscal comment et quand votre rémunération en actions est imposée'),
('au Canada, par exemple, les obligations émises par les municipalités','en France, par exemple, il n\'existe pas d\'équivalent des obligations municipales exonérées : les intérêts des obligations, y compris des emprunts d\'État (OAT), sont en principe soumis au prélèvement forfaitaire unique, sauf détention au sein d\'une enveloppe comme l\'assurance-vie'),
('au Canada, par exemple, le revenu qu\'une fiducie conserve','en France, par exemple, la fiducie existe dans le Code civil mais elle est peu utilisée par les particuliers pour transmettre un patrimoine, tandis que les trusts étrangers dont un résident français est constituant ou bénéficiaire sont soumis à des obligations déclaratives et à une fiscalité spécifiques, par conséquent faites-vous accompagner par un notaire et un conseiller fiscal'),
('au Canada, par exemple, l\'Agence du revenu du Canada traite généralement les cryptoactifs','en France, par exemple, les plus-values de cession d\'actifs numériques réalisées par un particulier sont en principe soumises au prélèvement forfaitaire unique, les échanges entre cryptoactifs étant en principe neutres fiscalement, les comptes détenus à l\'étranger doivent être déclarés, et les prestataires de services sur cryptoactifs sont encadrés par l\'AMF dans le cadre du règlement européen MiCA'),
('au Canada, par exemple, les réformes axées sur le client','en France, par exemple, les conseillers en investissements financiers sont immatriculés à l\'ORIAS et soumis à la réglementation de l\'AMF, et la directive MiFID II les oblige à indiquer si leur conseil est indépendant ou non et à détailler l\'ensemble des frais, par conséquent vérifiez le statut de votre conseiller sur le registre de l\'ORIAS'),
('au Canada, par exemple, il n\'existe pas de statut de négociateur','en France, par exemple, il n\'existe pas de statut fiscal de négociateur : les gains de bourse d\'un particulier relèvent en principe du régime des plus-values mobilières, et ce n\'est que dans des cas exceptionnels d\'opérations habituelles et professionnelles qu\'ils peuvent être imposés comme des bénéfices non commerciaux, par conséquent confirmez votre situation avec un conseiller fiscal'),
('au Canada, par exemple, le Fonds canadien de protection des investisseurs','en France, par exemple, le Fonds de garantie des dépôts et de résolution couvre les titres dans certaines limites chez un prestataire établi en France, mais pas chez un courtier étranger, et les comptes de titres ouverts à l\'étranger doivent être déclarés chaque année à l\'administration fiscale'),
('disposition réputée au Canada','absence d\'imposition de la plus-value latente au décès en France, mais droits de succession'),
]
n=0
for f in sorted(glob.glob('work/WHITE-L5-fr-FR/*.txt')):
    s=open(f,encoding='utf-8').read()
    for a,b in R:
        i=s.find(a)
        if i<0: continue
        if a.startswith('disposition'):
            s=s.replace(a,b); n+=1; continue
        j=s.find('.',i+len(a)) if not a.startswith('vérifiez') else i+len(a)
        s=s[:i]+b+s[j:]; n+=1
    open(f,'w',encoding='utf-8').write(s)
print('replaced',n)
